const ProductModal = ({ isOpen, onClose, onSubmit, initialData }) => {
  const [file, setFile] = useState(null);
  const [formData, setFormData] = useState({ title: '', price: '', image: '' });

  const handleFileChange = (e) => {
    setFile(e.target.files[0]);
  };

  const handleFormSubmit = async (e) => {
    e.preventDefault();
    let finalImageUrl = formData.image;

    // Если выбран новый файл, сначала загружаем его
    if (file) {
      try {
        finalImageUrl = await api.uploadImage(file);
      } catch (err) {
        alert("Ошибка при загрузке фото");
        return;
      }
    }

    onSubmit({ ...formData, image: finalImageUrl });
  };

  return (
    // ... верстка модалки ...
    <div className="form-group">
      <label>Загрузить фото товара:</label>
      <input type="file" accept="image/*" onChange={handleFileChange} />
      {formData.image && <p>Текущее фото: {formData.image}</p>}
    </div>
    // ... кнопки ...
  );
};
